#!/usr/bin/env bash

# Compiles the Grain modules the Grain converter generated by including every one of them in a check module that grain compiles and runs. Grain includes are
# relative paths so the hand written runtime, the Grain sources of the dependencies (META-INF/grain/src of their jars),
# and this project are copied to one tree first. This project's sources are written to <output>/src.
# Arguments: source_dir output_dir object_dir dependency_dir runtime_dir compiler "flags" artifactId fail_on_error

set -uo pipefail

export PATH="/usr/local/bin:/usr/bin:/bin:$PATH"

source_dir="$(cygpath -u "$1")"
output_dir="$(cygpath -u "$2")"
object_dir="$(cygpath -u "$3")"
dependency_dir="$(cygpath -u "$4")"
runtime_dir="$(cygpath -u "$5")"
compiler="$(cygpath -u "$6")"
read -r -a compiler_flags <<< "$7"
artifact="$8"
fail_on_error="${9:-true}"

if [ ! -d "$source_dir" ]; then
    echo "No Grain sources: $source_dir"
    exit 0
fi

rm -rf "$output_dir" "$object_dir"
tree="$object_dir/tree"
mkdir -p "$output_dir/src" "$tree"
cp -R "$source_dir/." "$output_dir/src/"
cp -R "$runtime_dir/." "$tree/"
if [ -d "$dependency_dir/src" ]; then
    cp -R "$dependency_dir/src/." "$tree/"
fi
cp -R "$source_dir/." "$tree/"

# A Windows program can not open a path over 260 characters, which a deep project folder plus a deep package reaches,
# so the check runs in a short temporary copy of the tree
short_tree="$(mktemp -d /tmp/grainXXXXXX)"
trap 'rm -rf "$short_tree"' EXIT
cp -R "$tree/." "$short_tree/"
cd "$short_tree" || exit 1

# Grain compiles every included module, so a module of a dependency's optional dependency (not transitive in Maven, like
# TsUtil for StringValidationUtil) is taken from the Grain jars installed in the local Maven repository.
local_repository="$(sed -n 's:.*<localRepository>\([^<]*\)</localRepository>.*:\1:p' "${USERPROFILE:-$HOME}/.m2/settings.xml" 2>/dev/null | head -1)"
[ -z "$local_repository" ] && local_repository="${USERPROFILE:-$HOME}/.m2/repository"
local_repository="$(cygpath -u "$local_repository")"
jar_index="$object_dir/grain-jar-index.txt"
for pass in 1 2 3 4 5; do
    missing="$(find . -type f -name '*.gr' | while IFS= read -r file; do
        directory="$(dirname "$file")"
        sed -n 's/^from "\([^"]*\.gr\)" include .*/\1/p' "$file" | while IFS= read -r include; do
            case "$include" in
                ./*|../*) target="$(realpath -m --relative-to=. "$directory/$include")"
                          [ -f "$target" ] || echo "$target" ;;
            esac
        done
    done | sort -u)"
    [ -z "$missing" ] && break
    if [ ! -f "$jar_index" ]; then
        find "$local_repository/org/allbinary" -name '*Grain-*.jar' ! -name '*-sources.jar' 2>/dev/null | while IFS= read -r jar; do
            unzip -Z1 "$jar" 2>/dev/null | sed -n "s|^META-INF/grain/src/\(.*\.gr\)$|\1 $jar|p"
        done > "$jar_index"
    fi
    found=0
    while IFS= read -r module; do
        jar="$(grep -m1 "^$module " "$jar_index" | cut -d' ' -f2-)"
        if [ -n "$jar" ]; then
            mkdir -p "$(dirname "$module")"
            unzip -p "$jar" "META-INF/grain/src/$module" > "$module"
            echo "Grain module from $(basename "$jar"): $module"
            found=1
        fi
    done <<< "$missing"
    [ "$found" = "0" ] && break
done

check="jcheck_$artifact.gr"
echo "module JCheck" > "$check"
count=0
while IFS= read -r file; do
    module="${file#"$source_dir"/}"
    name="$(basename "$module" .gr)"
    echo "from \"./$module\" include $name" >> "$check"
    count=$((count + 1))
done < <(find "$source_dir" -type f -name '*.gr' | sort)
echo "print(\"Grain compiled: $artifact\")" >> "$check"
echo "Grain modules: $count"

output="$("$compiler" "${compiler_flags[@]}" "$check" 2>&1)"
status=$?
echo "$output"
if [ "$status" = "0" ] && ! echo "$output" | grep -q -E "Error|error:"; then
    exit 0
fi
echo "Grain build failed: $artifact" >&2
if [ "$fail_on_error" = "true" ]; then
    exit 1
fi
exit 0
